namespace MuscleCuties.Infrastructure.PostgreSql.Models.App;

/// <summary>An authorised upload: the object key and the limits the client may write under. It exists so an abandoned
/// upload expires and its object can be cleaned, instead of being discovered later.</summary>
public sealed class PhotoUploadIntentRecord : ITenantRecord
{
    /// <summary>Generated by the client, so a retried request reuses the row instead of creating a second intent.</summary>
    public Guid Id { get; set; }
    /// <summary>The owner; every read is filtered by it through <c>ITenantRecord</c>.</summary>
    public Guid UserId { get; set; }
    /// <summary>The client's own key for this upload, unique per account, which is what makes the retry safe.</summary>
    public string IdempotencyKey { get; set; } = string.Empty;
    /// <summary>The one object key the upload may write to; the presigned URL is scoped to it.</summary>
    public string S3Key { get; set; } = string.Empty;
    /// <summary>The media type the upload is signed for, so the bytes cannot be stored as another type.</summary>
    public string ContentType { get; set; } = string.Empty;
    /// <summary>The size the client promised; the stored object must match it before the upload is accepted.</summary>
    public long DeclaredSizeBytes { get; set; }
    /// <summary>Checksum of the promised bytes, so a later read can prove the stored object is the one authorised.</summary>
    public string Sha256Checksum { get; set; } = string.Empty;
    /// <summary>When the intent was issued, in UTC.</summary>
    public DateTime CreatedAtUtc { get; set; }
    /// <summary>After this instant the intent is no longer usable and its pending object becomes cleanup work.</summary>
    public DateTime ExpiresAtUtc { get; set; }
    /// <summary>Lifecycle state; only <c>Pending</c> intents are still claimable by an upload.</summary>
    public string State { get; set; } = "Pending";
}

/// <summary>A queued deletion of a stored object. The row outlives the photo it refers to, which is why it carries the key
/// itself rather than a lookup.</summary>
public sealed class PhotoObjectCleanupRecord : ITenantRecord
{
    /// <summary>Primary key of the queue item.</summary>
    public Guid Id { get; set; }
    /// <summary>Owner of the photo, kept so the queue can be filtered and reported per account.</summary>
    public Guid UserId { get; set; }
    /// <summary>The photo whose object is being removed, kept for reporting after the photo row is gone.</summary>
    public Guid PhotoId { get; set; }
    /// <summary>The object key still to delete; copied here so it survives the photo row's deletion.</summary>
    public string S3Key { get; set; } = string.Empty;
    /// <summary>Why the object is going, kept for the audit trail.</summary>
    public string Reason { get; set; } = string.Empty;
    /// <summary>Earliest attempt time, so a just-abandoned upload can still be resumed before the deletion is tried.</summary>
    public DateTime NotBeforeUtc { get; set; }
    /// <summary>Pending, leased or done; only Pending rows are claimable.</summary>
    public string State { get; set; } = "Pending";
    /// <summary>Attempts so far, which drives the backoff between retries.</summary>
    public int AttemptCount { get; set; }
    /// <summary>The worker currently holding the row; null when nobody does.</summary>
    public Guid? LeaseToken { get; set; }
    /// <summary>Bumped on every lease, so a worker whose lease expired cannot write its result over the new holder's.</summary>
    public long LeaseGeneration { get; set; }
    /// <summary>When the lease lapses and the row may be claimed again.</summary>
    public DateTime? LeaseExpiresAtUtc { get; set; }
    /// <summary>The failure category of the last attempt, which is deliberate: a category, never an error message.</summary>
    public string? LastFailureCategory { get; set; }
    /// <summary>When the last attempt ran.</summary>
    public DateTime? LastAttemptAtUtc { get; set; }
    /// <summary>When the deletion was queued, in UTC.</summary>
    public DateTime CreatedAtUtc { get; set; }
    /// <summary>When the object was confirmed gone; set together with the terminal state.</summary>
    public DateTime? CompletedAtUtc { get; set; }
}

/// <summary>Owner-independent durable S3 cleanup identity. Contains only a generated opaque object key.</summary>
public sealed class PhotoObjectReconcileTargetRecord
{
    /// <summary>Primary key of the target.</summary>
    public Guid Id { get; set; }
    /// <summary>An opaque generated object key; nothing about the owner can be derived from it.</summary>
    public string TargetKey { get; set; } = string.Empty;
    /// <summary>Earliest time the reconciler may act on it.</summary>
    public DateTime NotBeforeUtc { get; set; }
    /// <summary>When the target was recorded.</summary>
    public DateTime CreatedAtUtc { get; set; }
    /// <summary>The worker holding the target; null when nobody does.</summary>
    public Guid? LeaseToken { get; set; }
    /// <summary>Bumped on every lease so an expired holder cannot write its result over the new one's.</summary>
    public long LeaseGeneration { get; set; }
    /// <summary>When the lease lapses and the target may be claimed again.</summary>
    public DateTime? LeaseExpiresAtUtc { get; set; }
}
